import itertools
import random

# Let's try to find a graph with 22 vertices, girth >= 7, 3-colorable, at least 27 edges
# We'll use a SAT/constraint approach

# First, let's think about the structure.
# A 22-cycle has girth 22 and is 2-colorable. We need 5 more edges.

# Let's try to add chords to a 22-cycle while maintaining girth >= 7

n = 22
# Base cycle edges
cycle_edges = [(i, (i+1)%n) for i in range(n)]

def girth(edges, n):
    """Compute girth of graph with given edges"""
    # BFS from each vertex
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = n + 1
    for s in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[s] = 0
        queue = [s]
        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u] and dist[u] + dist[v] + 1 < min_cycle:
                    min_cycle = dist[u] + dist[v] + 1
        if min_cycle <= 6:
            return min_cycle
    return min_cycle

def is_3_colorable(edges, n):
    """Check if graph is 3-colorable using simple backtracking"""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

# Let's try to add chords to the 22-cycle
# We need chords that don't create short cycles

# First, let's see what chords are possible
possible_chords = []
for i in range(n):
    for j in range(i+1, n):
        if (i, j) in cycle_edges or (j, i) in cycle_edges:
            continue
        # Check if adding this chord creates a cycle of length < 7
        # The chord creates two cycles along the cycle
        d1 = (j - i) % n
        d2 = n - d1
        if min(d1, d2) + 1 >= 7:
            possible_chords.append((i, j))

print(f"Number of possible chords: {len(possible_chords)}")
print(f"Example chords: {possible_chords[:10]}")

# Let's try random search
import random
random.seed(42)

best = 0
best_edges = None
for trial in range(100000):
    # Start with cycle edges
    edges = set(cycle_edges)
    # Shuffle possible chords
    random.shuffle(possible_chords)
    for chord in possible_chords:
        if len(edges) >= 27:
            break
        # Check if adding this chord keeps girth >= 7
        test_edges = edges | {chord}
        if girth(list(test_edges), n) >= 7:
            edges.add(chord)

    if len(edges) > best:
        best = len(edges)
        best_edges = edges.copy()
        print(f"Trial {trial}: found {len(edges)} edges, girth={girth(list(edges), n)}")
        if len(edges) >= 27:
            # Check 3-colorability
            if is_3_colorable(list(edges), n):
                print(f"Found 3-colorable graph with {len(edges)} edges!")
                break
            else:
                print(f"Not 3-colorable, continuing...")

print(f"Best: {best} edges")
if best_edges:
    print(f"Girth: {girth(list(best_edges), n)}")
    print(f"3-colorable: {is_3_colorable(list(best_edges), n)}")
